// ===== C: everything at the top. One bar: the place (its kind as an icon), the actions, then the view and the mode. One pane under it on the right. =====
const SC = { farm: 'M4 21V9m5 12V9m5 12V9m5 12V9M2 12h20M2 17h20', zone: 'M3 6.5 9 4l6 2.5L21 4v13.5L15 20l-6-2.5L3 20V6.5Zm6-2.5v13.5m6-11v13.5', sec: 'M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z', room: 'M4 10 12 4l8 6v10H4V10Z', pen: 'M5 5h14v14H5zM9.7 5v14M14.3 5v14', lane: 'M7 4v16M12 4v16M17 4v16' };
const TOPH = 60, PT = 12 + TOPH + 12;
const kindIc = (k) => '<span style="' + st({ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: '32px', height: '32px', borderRadius: '9px', background: K.press, color: K.ink, flex: 'none' }) + '">' + ic(SC[k], 17) + '</span>';
const where = (k, name, o) => { o = o || {}; return (o.noBack ? '' : sq(I.back)) + '<span style="' + st({ display: 'inline-flex', alignItems: 'center', gap: '9px', height: '40px', padding: '0 10px 0 6px' }) + '">' + kindIc(k) + t(name, { fontSize: '17px', fontWeight: 600, letterSpacing: '-.01em' }) + (o.dot ? '<i style="width: 8px; height: 8px; border-radius: 99px; background: ' + K.red + ';"></i>' : '') + '</span>'; };
const tbar = (left, right) => card({ left: '12px', right: '12px', top: '12px' }, left + '<span style="flex: 1;"></span>' + right, { display: 'flex', alignItems: 'center', gap: '2px', padding: '8px', height: TOPH + 'px' });
const view3 = (on) => '<span style="' + st({ display: 'inline-flex', gap: '2px', padding: '3px', borderRadius: '11px', background: K.press, marginRight: '4px' }) + '">' + ['3D', 'Plan'].map((x) => '<span style="' + st({ display: 'inline-flex', alignItems: 'center', height: '34px', padding: '0 12px', borderRadius: '8px', background: x === on ? '#FFFFFF' : 'transparent', boxShadow: x === on ? '0 1px 2px rgba(17,21,17,.12)' : 'none', fontSize: '13.5px', fontWeight: x === on ? 600 : 500 }) + '">' + x + '</span>').join('') + '</span>';
const done3 = '<span style="display: inline-flex; color: ' + K.ink + '; padding: 0 7px;">' + ic(I.undo, 18) + '</span><span style="display: inline-flex; color: #B5BCB3; padding: 0 7px;">' + ic(I.redo, 18) + '</span>' + sep + btn(I.check, 'Done', { dark: true });
const vtabs = (on, pigs) => btn(I.cal, 'Schedule', { on: on === 'sched' }) + btn(I.pig, 'Pigs', { n: pigs || '186', on: on === 'pigs' }) + btn(I.tool, 'Devices', { dot: K.red, on: on === 'dev' });
// the main pane: under the bar, full height to the bottom, fixed width
const pane = (head, body, foot) => panel(head, body, foot).replace("top: 12px; bottom: 12px;", 'top: ' + PT + 'px; bottom: 12px;');
const zoomCtl0 = (on) => card({ left: '12px', bottom: '12px' }, view3(on) + sep + ['M5 12h14', 'M12 5v14M5 12h14', 'M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5'].map((d, i) => '<span style="' + st({ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: '36px', height: '36px', borderRadius: '10px', color: K.ink }) + '">' + ic(i === 0 ? I.minus : i === 1 ? I.plus : d, 16) + '</span>').join(''), { display: 'flex', alignItems: 'center', gap: '2px', padding: '6px' });
const zoomCtl = zoomCtl0('3D');
const lanesBox = (on) => box(['A', 'B', 'C', 'D', 'E'].map((x) => ({ h: ic(SC.lane, 16, 1.8, K.muted) + t('Lane ' + x, { flex: 1, fontWeight: 500 }) + mu(x === 'E' ? '6 pens' : '50 stalls') + ic(I.chev, 15, 1.8, K.faint) })));

const frames = {
  v1: { cap: 'At rest: one bar across the top. The place says its kind with an icon (a room here), then what you can open, then Select at the right end. 3D or Plan and zoom sit at the bottom left. The map has everything else.', html: () => tbar(where('room', 'Gestation 2', { dot: true }) + sep + vtabs(''), btn(I.select, 'Select')) + zoomCtl },
  v2: { cap: 'Schedule opens the main pane, under the bar and to the bottom edge. The bar keeps its full width, so the pane never cuts into it.', html: () => tbar(where('zone', 'Production Zone 1', { dot: true }) + sep + vtabs('sched', '1,375'), btn(I.select, 'Select')) + pane(phead('Schedule', 'Production Zone 1 · this week'), sched()) + zoomCtl },
  v3: { cap: 'A row opens its task in the same pane, one camera move to Farrowing Room 4. The bar now says the room; the back chip, Esc or empty map return both to Production Zone 1.', html: () => tbar(where('room', 'Farrowing Room 4') + sep + vtabs('sched', '26'), btn(I.select, 'Select')) + pane(phead('Move into Farrowing Room 4', 'Batch 33 · day 2 of 3', { back: 'Schedule · Production Zone 1' }), sec('Progress', '26 sows') + box([{ h: '<div style="padding: 14px 0;">' + ring(26, 26, K.green, 'All moved in') + '</div>' }]) + sec('Next') + box([{ h: t('Fri 6 Nov', { width: '86px', color: K.muted, fontSize: '13px' }) + t('Farrowing starts, ~6 litters') }, { h: t('Sat 7 Nov', { width: '86px', color: K.muted, fontSize: '13px' }) + t('Farrowing, ~14 litters') }])) + zoomCtl },
  v4: { cap: 'A pig: the bar says the pen, the pane holds her record, the camera puts the pen in the free map.', html: () => tbar(where('pen', 'Pen C24') + sep + vtabs(''), btn(I.select, 'Select')) + pane(phead('205783', 'Sow · C24 · Gestation 2', { back: 'Gestation 2' }), sec('Now') + box([{ h: t('Gestation', { fontSize: '16px', fontWeight: 600 }) + mu('day 78 of 115') }]) + sec('Details') + '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">' + [['Parity', '2'], ['Breed', 'LY'], ['Weight', '192 kg'], ['Backfat', '13 mm'], ['Teats', '14'], ['Feed', '2.6 kg / day']].map((x) => '<div style="padding: 10px 12px; background: #FFFFFF; border: 1px solid ' + K.line + '; border-radius: 12px;"><div style="font-size: 12.5px; color: ' + K.muted + ';">' + x[0] + '</div><div style="font-size: 15px; font-weight: 600;">' + x[1] + '</div></div>').join('') + '</div><div style="display: flex; gap: 8px; margin-top: 16px;">' + fbtn(ic(I.chart, 16) + '&nbsp; Performance') + fbtn(ic(I.log, 16) + '&nbsp; Log') + '</div>') + zoomCtl },
  e1: { cap: 'Edit, at rest: the same bar. Add and the room\'s actions sit after the place; undo, redo and Done at the right end, Done the only dark button. 3D or Plan sits at the bottom left with zoom. No card, no pane: the map is clear, you click a lane or a room on it.', html: () => tbar(where('room', 'Gestation 1') + sep + btn(I.plus, 'Add', { caret: true }) + btn(I.corners, 'Reshape walls') + btn(I.copy, 'Duplicate') + btn(I.more, 'More'), done3) + zoomCtl },
  e2: { cap: 'Placing a row: Plan, and the bar itself becomes the guide. Cancel at its right end, where Done was.', html: () => tbar('<span style="' + st({ display: 'inline-flex', alignItems: 'center', justifyContent: 'center', width: '40px', height: '40px', borderRadius: '11px', background: K.ink, color: '#FFFFFF', margin: '0 4px' }) + '">' + ic(I.row, 18) + '</span><span style="display: flex; flex-direction: column; gap: 1px; padding-left: 6px;">' + t('Place a row in Gestation 1', { fontWeight: 600, fontSize: '15px' }) + mu('A green box follows your pointer. Click by the door or at the far end.') + '</span>', '<span style="' + st({ display: 'inline-flex', alignItems: 'center', height: '40px', padding: '0 14px', borderRadius: '10px', boxShadow: 'inset 0 0 0 1px #D5DACF', fontWeight: 600 }) + '">Cancel</span>') + zoomCtl0('Plan') },
  e3: { cap: 'Add pens: the main pane opens, the same pane as everything else, here from the lane. Pen type and count, then Add; the back chip returns to the lane.', html: () => tbar(where('room', 'Gestation 2') + sep + btn(I.plus, 'Add', { caret: true }) + btn(I.corners, 'Reshape walls') + btn(I.more, 'More'), done3) + pane(phead('Add pens to lane C', 'After C22, from the door', { back: 'Lane C' }), sec('Pen type') + box([{ h: sw('#A7CDAE') + t('Gestation stall', { fontWeight: 500 }) + mu('65 × 210 cm') + '<span style="flex: 1;"></span>' + ic(I.check, 15, 2.2) }, { h: sw('#9FD3C8') + t('Group pen', { fontWeight: 500 }) + mu('300 × 500 cm') }, { h: sw('#C9B6E4') + t('Gilt pen', { fontWeight: 500 }) + mu('300 × 500 cm') }, { h: ic(I.plus, 16) + t('New pen type', { fontWeight: 500 }) }]) + sec('How many', 'C23 – C26') + box([{ h: t('Pens', { flex: 1, fontWeight: 500 }) + step('4') }]), fbtn('Cancel') + fbtn('Add 4 pens', 'pri')) + zoomCtl },
  e4: { cap: 'A lane picked on the map: its page opens in the pane, its pens from the door and its actions, Remove apart at the end. Exactly how a pig opens in the Farm view.', html: () => tbar(where('room', 'Gestation 2') + sep + btn(I.plus, 'Add', { caret: true }) + btn(I.corners, 'Reshape walls') + btn(I.more, 'More'), done3) + pane(phead('Lane C', 'Lane · Z1-GES-2-C · 22 pens'), sec('Pens', 'from the door') + box([{ h: sw('#A7CDAE') + '<span style="flex: 1; display: flex; flex-direction: column;">' + t('Gestation stall', { fontWeight: 500 }) + mu('C1–C12', { fontSize: '12.5px' }) + '</span>' + step('12') }, { h: sw('#9FD3C8') + '<span style="flex: 1; display: flex; flex-direction: column;">' + t('Group pen', { fontWeight: 500 }) + mu('C13–C22', { fontSize: '12.5px' }) + '</span>' + step('10') }]) + sec('Actions') + box([{ h: ic(I.plus, 17) + t('Add pens', { fontWeight: 500 }) + '<span style="flex: 1;"></span>' + ic(I.chev, 15, 1.8, K.faint) }, { h: ic(I.copy, 17) + t('Copy lane', { fontWeight: 500 }) }]) + '<div style="margin-top: 10px;">' + box([{ h: ic(I.trash, 17) + t('Remove lane', { fontWeight: 500 }), red: true }]) + '</div>') + zoomCtl }
};

